when HTTP_REQUEST {
   set mypick [LB::persist]
   log local0. "The persistence entry is: $mypick and the key is [LB::persist key]"
   if { [lindex $mypick 1] ne "0" }{
     # Execute the pick
     eval [lindex [LB::persist] 1]]
   } else {
     log local0. "No persistence record found"
   }
}
